import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useMessage } from '../../context/MessageContext';
import { jobApi } from '../../api/api';
import '../../styles/RecommendationsPage.css';
import 'bootstrap-icons/font/bootstrap-icons.css';

function RecommendationsPage() {
  const { currentUser } = useAuth();
  const { setMessage, setLoading } = useMessage();
  const [recommendedJobs, setRecommendedJobs] = useState([]);
  const [selectedJob, setSelectedJob] = useState(null);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const menuRef = useRef();

  useEffect(() => {
    if (currentUser?.username) {
      fetchRecommendations();
    }
  }, [currentUser]);

  const fetchRecommendations = async () => {
    setLoading(true);
    try {
      const response = await jobApi.getRecommendations(currentUser.username);
      setRecommendedJobs(response);
    } catch (error) {
      setMessage('Failed to fetch recommendations: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const openJobDetails = (job) => {
    setSelectedJob(job);
  };

  const closeJobDetails = () => {
    setSelectedJob(null);
  };

  // Handle outside click for radial menu
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (menuRef.current && !menuRef.current.contains(e.target)) {
        setIsMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="recommendations-wrapper">
      <div className="background"></div>
      <div className="header">
        <i className="bi bi-stars header-icon"></i>
        <h2 className="header-text">AI-Powered Job Recommendations</h2>
      </div>

      <div className="recommendation-grid">
        {recommendedJobs.map((job, index) => {
          const matchScore = job.matchScore; // Float value
          const displayMatchScore =
            matchScore !== undefined ? `Match: ${(matchScore * 100).toFixed(0)}%` : null;

          return (
            <div key={index} className="job-card" onClick={() => openJobDetails(job)}>
              <h3>{job.title}</h3>
              <p>{job.location}</p>
              {displayMatchScore && <p className="match-score">{displayMatchScore}</p>}
              <i className="bi bi-info-circle-fill info-icon"></i>
            </div>
          );
        })}
      </div>

      {selectedJob && (
        <div className="job-detail-overlay" onClick={closeJobDetails}>
          <div className="job-detail-card" onClick={(e) => e.stopPropagation()}>
            <h2>{selectedJob.title}</h2>
            <p>
              <strong>Description:</strong> {selectedJob.description}
            </p>
            <p>
              <strong>Skills:</strong> {selectedJob.skills?.join(', ')}
            </p>
            <p>
              <strong>Experience:</strong> {selectedJob.experience}
            </p>
            <p>
              <strong>Location:</strong> {selectedJob.location}
            </p>
            <p>
              Posted by: <span className="poster-username">{selectedJob?.posterUsername || 'Unknown'}</span>{' '}
              on{' '}
              {selectedJob?.postedDate
                ? new Date(selectedJob.postedDate).toLocaleDateString()
                : 'Unknown Date'}
            </p>
            <button onClick={closeJobDetails}>Close</button>
          </div>
        </div>
      )}

      {/* Radial Menu */}
      <div className="radialMenuWrapper">
        <button className="radialMenuBtn" onClick={() => setIsMenuOpen(!isMenuOpen)}>
          <i className={`bi ${isMenuOpen ? 'bi-x' : 'bi-plus'}`}></i>
        </button>

        <div className={`menuItems ${isMenuOpen ? 'menuItemsActive' : ''}`} ref={menuRef}>
          <button onClick={fetchRecommendations} title="Refresh">
            <i className="bi bi-arrow-clockwise"></i>
          </button>
          {/* Add more options here as needed */}
        </div>
      </div>
    </div>
  );
}

export default RecommendationsPage;
